import ast

# Parse the code for syntax validation only
user_code = code
try:
    tree = ast.parse(user_code)
except SyntaxError as e:
    raise AssertionError(f'Syntax error in your code: {e}')

# Check for numpy import
found_numpy = False
for node in ast.walk(tree):
    if isinstance(node, ast.Import) and any(name.name == 'numpy' for name in node.names):
        found_numpy = True
    if isinstance(node, ast.ImportFrom) and node.module == 'numpy':
        found_numpy = True

if not found_numpy:
    raise AssertionError('Task 1: Missing import numpy (check syntax)')

# Check for np.array() call
found_array = False
for node in ast.walk(tree):
    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute):
            if isinstance(node.func.value, ast.Name) and node.func.value.id == 'np' and node.func.attr == 'array':
                found_array = True

if not found_array:
    raise AssertionError('Task 2: Missing np.array() call')

# Check for print statements (at least 3)
print_calls = [node for node in ast.walk(tree) if isinstance(node, ast.Call) and 
               isinstance(node.func, ast.Name) and node.func.id == 'print']

if len(print_calls) < 3:
    raise AssertionError('Tasks 3-5: Expected at least 3 print statements')

# Check for dtype attribute access
found_dtype = False
found_shape = False
for node in ast.walk(tree):
    if isinstance(node, ast.Attribute):
        if node.attr == 'dtype':
            found_dtype = True
        if node.attr == 'shape':
            found_shape = True

if not found_dtype:
    raise AssertionError('Task 4: Missing .dtype attribute access')
if not found_shape:
    raise AssertionError('Task 5: Missing .shape attribute access')

print('TEST_PASSED')
